test('bhv authbasic 002 every generated basic wrapper sends the basic header and masks the password', function (): void {
    $wrappers = 0;
    foreach (glob(__DIR__ . '/../lib/Auth/*Authenticator.php') ?: [] as $file) {
        $class = 'PetstoreClient\\Auth\\' . basename($file, '.php');
        if (!is_subclass_of($class, BasicAuthenticator::class)) {
            continue;
        }
        $wrappers++;
        $reflection = new \ReflectionClass($class);

        $auth = $reflection->newInstance('https://api.example.com', 'wrapper-user', 'wrapper-pass');
        expect($auth->getAuthHeaders())
            ->toBe(['Authorization' => 'Basic ' . base64_encode('wrapper-user:wrapper-pass')]);
        expect(print_r($auth, true))->not->toContain('wrapper-pass');
        expect(fn () => $reflection->newInstance('https://api.example.com', 'bad:user', 'wrapper-pass'))
            ->toThrow(\InvalidArgumentException::class);
    }
    expect($wrappers)->toBeGreaterThan(0);
});

/**
 * Runs $body with the user name and password environment variables of PetStoreBasicAuthenticator set (null unsets one), then restores them.
 */
function withBasicEnvironment(?string $user, ?string $secret, callable $body): void
{
    $names = ['SWAGGER_PETSTORE_OPEN_API_3_0_PET_STORE_BASIC_USERNAME' => $user, 'SWAGGER_PETSTORE_OPEN_API_3_0_PET_STORE_BASIC_PASSWORD' => $secret];
    $previous = [];
    foreach ($names as $name => $value) {
        $previous[$name] = getenv($name);
        putenv($value === null ? $name : $name . '=' . $value);
    }
    try {
        $body();
    } finally {
        foreach ($previous as $name => $value) {
            putenv($value === false ? $name : $name . '=' . $value);
        }
    }
}

